// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import { AppUI as NewUI } from './index';
import { AppUI as OldUI } from './__old_index';

const SCREENS = ['main', 'play', 'custom', 'ranked', 'settings', 'profile', 'leaderboard'] as const;

describe('reformat parity', () => {
  it('renders identical markup on every screen', () => {
    for (const screen of SCREENS) {
      const oldRoot = document.createElement('div');
      const newRoot = document.createElement('div');
      const oldUi = new OldUI(oldRoot as any) as any;
      const newUi = new NewUI(newRoot as any) as any;
      oldUi.navigate(screen);
      newUi.navigate(screen);
      expect(newRoot.innerHTML, screen).toBe(oldRoot.innerHTML);
    }
  });
});
EOF
npx vitest run src/ui/__parity.test.ts 2>&1 | tail -20
echo "parity exit=${PIPESTATUS[0]}"
rm -f src/ui/__old_index.ts src/ui/__parity.test.ts
